mapper.select:
select info_id, user_name, ipaddr, status, msg, access_time, platform_source, belong_sys from sys_logininfor


        AND ipaddr like concat('%', #{ipaddr}, '%')


        AND status = #{status}


        AND user_name = #{userName}


        and date_format(access_time,'%y%m%d') >= date_format(#{params.beginTime},'%y%m%d')


        and date_format(access_time,'%y%m%d') <= date_format(#{params.endTime},'%y%m%d')


        AND platform_source = #{platformSource}


        AND belong_sys = #{belongSys}


order by info_id desc,access_time desc
